use std::fs

struct Tree {
    keys: Vec<int>,
    left: Vec<int>,
    right: Vec<int>,
    root: int,
    found: bool,
    out: Vec<string>,
}

impl Tree {
    fn has(self, x: int) -> bool {
        let mut n = self.root
        while n >= 0 {
            let k = self.keys[n]
            if x == k { return true }
            if x < k { n = self.left[n] } else { n = self.right[n] }
        }
        false
    }

    fn insert(self, x: int) {
        let id: int = self.keys.len()
        self.keys.push(x)
        self.left.push(-1)
        self.right.push(-1)
        if self.root < 0 {
            self.root = id
            return
        }
        let mut n: int = self.root
        loop {
            if x < self.keys[n] {
                if self.left[n] < 0 {
                    self.left[n] = id
                    break
                }
                n = self.left[n]
            } else {
                if self.right[n] < 0 {
                    self.right[n] = id
                    break
                }
                n = self.right[n]
            }
        }
    }

    fn del(self, n: int, x: int) -> int {
        if n < 0 { return -1 }
        let k = self.keys[n]
        if x < k {
            let l = self.del(self.left[n], x)
            self.left[n] = l
            n
        } else if x > k {
            let r = self.del(self.right[n], x)
            self.right[n] = r
            n
        } else {
            self.found = true
            if self.left[n] < 0 {
                self.right[n]
            } else if self.right[n] < 0 {
                self.left[n]
            } else {
                let s = self.minnode(self.right[n])
                let sk = self.keys[s]
                self.keys[n] = sk
                let r = self.del(self.right[n], sk)
                self.right[n] = r
                n
            }
        }
    }

    fn minnode(self, start: int) -> int {
        let mut n: int = start
        while self.left[n] >= 0 { n = self.left[n] }
        n
    }

    fn maxnode(self, start: int) -> int {
        let mut n: int = start
        while self.right[n] >= 0 { n = self.right[n] }
        n
    }

    fn height(self, n: int) -> int {
        if n < 0 { return 0 }
        let a = self.height(self.left[n])
        let b = self.height(self.right[n])
        if a > b { a + 1 } else { b + 1 }
    }

    fn walk(self, n: int) {
        if n < 0 { return }
        self.walk(self.left[n])
        let k = self.keys[n]
        self.out.push("${k}")
        self.walk(self.right[n])
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { keys: [], left: [], right: [], root: -1, found: false, out: [] }
    for line in text.lines() {
        let parts: Vec<string> = line.trim().split(" ").collect()
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse::<int>().unwrap_or(0)
            if t.has(x) { println("dup") } else {
                t.insert(x)
                println("ok")
            }
        } else if cmd == "contains" {
            let x: int = parts[1].parse::<int>().unwrap_or(0)
            if t.has(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x: int = parts[1].parse::<int>().unwrap_or(0)
            t.found = false
            let r = t.del(t.root, x)
            t.root = r
            if t.found { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            t.out = []
            t.walk(t.root)
            if t.out.len() == 0 { println("<empty>") } else { println(t.out.join(" ")) }
        } else if cmd == "height" {
            println("${t.height(t.root)}")
        } else if cmd == "min" {
            if t.root < 0 { println("empty") } else {
                let m = t.minnode(t.root)
                println("${t.keys[m]}")
            }
        } else if cmd == "max" {
            if t.root < 0 { println("empty") } else {
                let m = t.maxnode(t.root)
                println("${t.keys[m]}")
            }
        }
    }
}

